import { expect, test } from '@playwright/test';
import { LARGE_URL } from '../playwright.config';

// Behaviour that only matters, or only shows, in a catalog of more than a
// hundred skills. The catalog is generated by scripts/make-playground.mjs.

test('a large catalog opens on skills only, and the filter narrows it', async ({ page }) => {
  await page.goto(`${LARGE_URL}architecture/`);
  const graph = page.getByTestId('graph');
  const nodes = graph.locator('.react-flow__node');
  const shown = page.getByRole('status', { name: 'Skills shown' });

  // Files start hidden, and the page says so.
  await expect(shown).toHaveText('153 skills');
  await expect(nodes).toHaveCount(153);
  await expect(graph.getByText('Files are hidden in a catalog this size')).toBeVisible();
  await expect(page.getByRole('button', { name: /Scripts/ })).toHaveAttribute('aria-pressed', 'false');

  await page.getByRole('searchbox', { name: 'Filter the graph' }).fill('migration');
  await expect(shown).toHaveText(/^\d+ of 153 skills$/);
  const count = await nodes.count();
  expect(count).toBeGreaterThan(0);
  expect(count).toBeLessThan(30);
  for (const text of await nodes.allInnerTexts()) expect(text).toContain('migration');
});

test('only the nodes on screen are rendered once there are more than a hundred', async ({ page }) => {
  await page.goto(`${LARGE_URL}architecture/`);
  const nodes = page.getByTestId('graph').locator('.react-flow__node');
  await page.getByRole('button', { name: /Scripts/ }).click();
  await page.getByRole('button', { name: /References/ }).click();

  // Fitted to the view, the whole graph is on screen: every node is rendered.
  await page.getByRole('button', { name: /fit view/i }).click();
  await expect.poll(() => nodes.count()).toBeGreaterThan(500);
  const all = await nodes.count();

  // Zoomed in, most of the graph is off screen and is left out of the page.
  for (let i = 0; i < 6; i++) await page.getByRole('button', { name: /zoom in/i }).click();
  await expect.poll(() => nodes.count()).toBeLessThan(all / 3);
  expect(await nodes.count()).toBeGreaterThan(0);

  // Fitting again brings every node back.
  await page.getByRole('button', { name: /fit view/i }).click();
  await expect.poll(() => nodes.count()).toBe(all);
});

test('the sidebar can show only the skills with errors or with warnings', async ({ page, request }) => {
  // Work the expected numbers out from the catalog itself.
  const catalog = (await (await request.get(`${LARGE_URL}data/catalog.json`)).json()) as {
    skills: { name: string; diagnostics: { severity: string }[] }[];
  };
  const withSeverity = (severity: string) =>
    catalog.skills.filter((skill) => skill.diagnostics.some((d) => d.severity === severity));
  const errors = withSeverity('error');
  const warnings = withSeverity('warning');
  expect(errors.length).toBeGreaterThan(0);
  expect(warnings.length).toBeGreaterThan(0);

  await page.goto(LARGE_URL);
  const nav = page.getByRole('navigation', { name: 'Skills' });
  const status = page.getByRole('group', { name: 'Filter skills by status' });
  await expect(nav.getByRole('link')).toHaveCount(153);
  await expect(status.getByRole('button', { name: /^All/ })).toHaveAttribute('aria-pressed', 'true');

  // Errors: exactly the skills with an error, each marked as such; empty groups disappear.
  await status.getByRole('button', { name: `Errors ${errors.length}` }).click();
  await expect(nav.getByRole('link')).toHaveCount(errors.length);
  await expect(nav.getByLabel('Has errors')).toHaveCount(errors.length);
  expect(await nav.getByRole('button').count()).toBeLessThanOrEqual(3);

  // Warnings: a different set, including the skills with a broken link.
  await status.getByRole('button', { name: `Warnings ${warnings.length}` }).click();
  await expect(nav.getByRole('link')).toHaveCount(warnings.length);
  await expect(nav.getByRole('link', { name: 'dashboard-triage' })).toBeVisible();

  // The status filter also narrows search results.
  const search = page.getByRole('searchbox', { name: 'Search skills' });
  await search.fill('triage');
  const results = page.getByRole('region', { name: 'Search results' });
  await expect(results.getByRole('link', { name: /^dashboard-triage/ })).toBeVisible();
  const narrowed = await results.locator('a[aria-current], a[href*="/skills/"]').count();
  await status.getByRole('button', { name: /^All/ }).click();
  await expect.poll(() => results.locator('a[aria-current], a[href*="/skills/"]').count()).toBeGreaterThan(narrowed);

  await search.fill('');
  await expect(nav.getByRole('link')).toHaveCount(153);
});
